D = {d['bot']: d for d in S['deathsSkel']}


def death(bot, cause, chain, **kw):
    d = dict(D[bot])
    d['cause'] = cause
    d['chain'] = chain
    d.update(kw)
    return d


def ydeath(bot, pid, died, peak, last_log, cause, chain, stype='inferred'):
    return {'bot': bot, 'pid': pid, 'instance': 'Y（无录像）', 'leftT': None, 'diedT': died, 'lastLogT': last_log, 'peakTerr': peak, 'takers': [],
            'cause': cause, 'chain': chain, 'statementType': stype}


